/// One node to bootstrap a devnet from.
///
/// Declared here rather than taken from
struct SeedNode {
    /// Ed25519, 64 hex characters. Not the X25519 key a session id is built from.
    std::string ed25519_pubkey_hex;
    /// A dotted quad: libsession dials it itself and resolves no host names anywhere.
    std::string ip;
    double https_port;
    double omq_port;

    SeedNode(std::string ed25519_pubkey_hex_, std::string ip_, double https_port_, double omq_port_) :
            ed25519_pubkey_hex{std::move(ed25519_pubkey_hex_)}, ip{std::move(ip_)}, https_port{std::move(https_port_)}, omq_port{std::move(omq_port_)} {}
};

enum class UrlScheme {
    http,
    https,
};

template <>
struct EnumTraits<UrlScheme> {
    static constexpr std::string_view name = "UrlScheme";
    static constexpr std::array<std::string_view, 2> names{"http", "https"};

    static constexpr std::string_view to_string(UrlScheme value) {
        return names[static_cast<std::size_t>(value)];
    }

    static constexpr std::optional<UrlScheme> parse(std::string_view text) {
        for (std::size_t i = 0; i < names.size(); i++)
            if (names[i] == text)
                return static_cast<UrlScheme>(i);
        return std::nullopt;
    }
};

/// A file server that is not the built-in one.
///
/// Left out, every network uses the built-in server for its netid - and devnet has none of its own,
/// so it would use **mainnet's**: production storage, reached over a sandbox, with nothing
/// afterwards to show it happened.
struct FileServerConfig {
    ::session_bridge::UrlScheme scheme;
    std::string host;
    double port;
    /// The server's **Ed25519** pubkey, which its QUIC endpoint is identified by. libsession derives
    /// the X25519 key onion requests to it are encrypted with from this, so that one is wrong here.
    std::string ed25519_pubkey_hex;

    FileServerConfig(::session_bridge::UrlScheme scheme_, std::string host_, double port_, std::string ed25519_pubkey_hex_) :
            scheme{std::move(scheme_)}, host{std::move(host_)}, port{std::move(port_)}, ed25519_pubkey_hex{std::move(ed25519_pubkey_hex_)} {}
};

/// How requests reach the network.
///
/// Session Router is what mainnet and testnet ship, and is the default for both. Onion requests are
/// the other production path, and a devnet's default - Session Router refuses a devnet outright, so
/// a devnet takes onion requests or direct, never Session Router. Direct sends each request
/// straight to the node it is for, with no path: for development and diagnosis, since a node sees
/// the address of the device asking.
///
/// Settable so that the transport can be chosen independently of the network: the two paths share
/// only a ten-method interface, and uploads, downloads, connection status and retry behaviour are
/// separate implementations on each side. Without this, testing the shipped transport and using a
/// disposable network are mutually exclusive.
enum class RouterKind {
    onion_requests,
    session_router,
    direct,
};

template <>
struct EnumTraits<RouterKind> {
    static constexpr std::string_view name = "RouterKind";
    static constexpr std::array<std::string_view, 3> names{"onion-requests", "session-router", "direct"};

    static constexpr std::string_view to_string(RouterKind value) {
        return names[static_cast<std::size_t>(value)];
    }

    static constexpr std::optional<RouterKind> parse(std::string_view text) {
        for (std::size_t i = 0; i < names.size(); i++)
            if (names[i] == text)
                return static_cast<RouterKind>(i);
        return std::nullopt;
    }
};

/// Attach a network, or replace the one attached. Declining to attach is how an app stays
/// offline, and that is an init option rather than a command.
///
/// Carries everything the network needs rather than leaving half of it remembered from init, so
/// that a refusal leaves the client on whatever it had. "mainnet", "testnet" or "devnet".
struct AttachNetworkCommand {
    static constexpr std::string_view type_tag = "attachNetwork";

    std::string netid;
    std::optional<std::vector<::session_bridge::SeedNode>> seed_nodes;
    std::optional<::session_bridge::FileServerConfig> file_server;
    /// Defaults to session-router on mainnet and testnet, onion requests on devnet.
    std::optional<::session_bridge::RouterKind> router;

    AttachNetworkCommand(std::string netid_, std::optional<std::vector<::session_bridge::SeedNode>> seed_nodes_, std::optional<::session_bridge::FileServerConfig> file_server_, std::optional<::session_bridge::RouterKind> router_) :
            netid{std::move(netid_)}, seed_nodes{std::move(seed_nodes_)}, file_server{std::move(file_server_)}, router{std::move(router_)} {}
};

/// Fill the service-node cache before there is an account to use it, so the first attach is not
/// also the first refresh.
///
/// **Takes no arguments on purpose.** It warms the network the client would attach -- the one
/// given at init -- because a cache warmed for any other is a cache the attach cannot use, and a
/// netid passed separately could disagree with it.
///
/// Answers true when the pool has nodes in it. Refused, with false, where there is nothing to
/// warm or nothing to gain: no network configured, a network already attached (two live Networks
/// would both refresh), or a warm already in flight.
///
/// The instance is dropped before the client attaches rather than left beside it, which is what
/// makes this a warm rather than a second network.
struct WarmNetworkCacheCommand {
    static constexpr std::string_view type_tag = "warmNetworkCache";
};

/// Whether the attached network can carry traffic now. `disconnected` where none is attached.
///
/// Asked once and then followed by `network-status-changed`, the way every list here is: a
/// renderer that reloads, or a store that subscribes after the network came up, has missed the
/// events that said so.
struct GetNetworkStatusCommand {
    static constexpr std::string_view type_tag = "getNetworkStatus";
};

/// How often libsession polls the swarm, in milliseconds. Its default is 20 seconds, which is a
/// long time to wait for a test and about right for a person.
///
/// Takes effect by replacing the running ticker, so the next poll is a full interval away rather
/// than when the old one would have fired; setting it before a network is attached therefore
/// costs no initial delay. Nothing serialises polls against each other, so an interval short
/// enough that one is still outstanding when the next fires gets overlapping requests - wasteful
/// rather than wrong, since a handler already has to tolerate seeing a message twice.
///
/// The floor is 1ms: zero or negative is refused rather than read as "never" or "always".
struct SetPollIntervalCommand {
    static constexpr std::string_view type_tag = "setPollInterval";

    double interval_ms;

    explicit SetPollIntervalCommand(double interval_ms_) :
            interval_ms{std::move(interval_ms_)} {}
};

/// Run one poll cycle to completion: the primitive every OS background budget wants. Android's
/// WorkManager job, iOS's BGAppRefreshTask and a push-triggered fetch all reduce to it.
struct PollOnceCommand {
    static constexpr std::string_view type_tag = "pollOnce";
};

/// Closes the database before the OS suspends the process: destroys the Client once it has no
/// outbound work left or after `waitMs`, whichever is first. If destroying it is still not done
/// `interruptMs` after the command, the database's SQL is interrupted so that it can finish, and
/// whatever statement was running is rolled back.
///
/// For iOS, which kills a suspended app holding a lock on a file in its shared container
/// (0xdead10cc), and the database is in the app group so the notification extension can open
/// it. While it waits, the Client works as before and `reopenClient` cancels the close; once it is
/// destroying, every request but `reopenClient` is refused at once rather than left waiting.
/// Answers `clientClosed`.
struct CloseClientCommand {
    static constexpr std::string_view type_tag = "closeClient";

    double wait_ms;
    double interrupt_ms;

    CloseClientCommand(double wait_ms_, double interrupt_ms_) :
            wait_ms{std::move(wait_ms_)}, interrupt_ms{std::move(interrupt_ms_)} {}
};

/// Undoes `closeClient`: cancels it while it is still waiting for outbound work, or builds the
/// Client again and attaches its network once it has closed. Answers `ok` when the Client is
/// there again; nothing to do if it never closed.
struct ReopenClientCommand {
    static constexpr std::string_view type_tag = "reopenClient";
};

/// The push server's name for the service that delivers a device's pushes. `apns-sandbox` is APNs
/// for a build signed for development, whose tokens production APNs refuses.
enum class PushService {
    apns,
    apns_sandbox,
    firebase,
    huawei,
};

template <>
struct EnumTraits<PushService> {
    static constexpr std::string_view name = "PushService";
    static constexpr std::array<std::string_view, 4> names{"apns", "apns-sandbox", "firebase", "huawei"};

    static constexpr std::string_view to_string(PushService value) {
        return names[static_cast<std::size_t>(value)];
    }

    static constexpr std::optional<PushService> parse(std::string_view text) {
        for (std::size_t i = 0; i < names.size(); i++)
            if (names[i] == text)
                return static_cast<PushService>(i);
        return std::nullopt;
    }
};

/// Subscribes this device to pushes for the account through `service`, or renews or changes its
/// subscription; `token` is what the service issued (an APNs token in hex, an FCM or Huawei token
/// as given). Sends only when needed: nothing is sent when the stored subscription already
/// matches and is under a day old, so this is cheap to call on every launch. A changed token
/// unsubscribes the old one too.
///
/// Answers `bool`: true when a request went out and was accepted, false when nothing needed
/// sending. Refused without a network or an account.
///
/// `force` sends whatever is stored. A reinstall on iOS can keep the database, which lives in the
/// app group, while the push server has dropped the subscription; the stored one then matches
/// and nothing would be sent for up to a day.
struct SetPushTokenCommand {
    static constexpr std::string_view type_tag = "setPushToken";

    ::session_bridge::PushService service;
    std::string token;
    std::optional<bool> force;

    SetPushTokenCommand(::session_bridge::PushService service_, std::string token_, std::optional<bool> force_) :
            service{std::move(service_)}, token{std::move(token_)}, force{std::move(force_)} {}
};

